<script lang="ts">import{onMount}from'svelte';import{locations}from'../fixtures/locations';import type{Profile}from'../domain/publication';import{parseRoute}from'./routeState';import{filterLocations,initialFilters,type FilterState}from'../features/locations/filterState';import MapView from'../map/MapView.svelte';import{makeExportModel}from'../export/exportModel';import{previewExport}from'../export/previewExport';let profile:Profile='curated';let scenario='ready';let selected=locations[0];let search='';let region='all';let filters:FilterState=initialFilters;let showMap=false;let showExport=false;$:filters={search,region,category:'all'};$:source=profile==='community'?locations.slice(0,1):locations;$:visibleLocations=filterLocations(source,filters);$:exportPreview=previewExport(makeExportModel(visibleLocations,profile));const sync=()=>{const r=parseRoute(window.location.hash);if(r.kind==='location'){profile=r.profile;selected=locations.find(x=>x.id===r.facilityId)??locations[0]}else if(r.kind==='home'){profile=r.profile}};const select=(id:string)=>{selected=locations.find(x=>x.id===id)??selected;window.location.hash=`/locations/${id}?profile=${profile}`};onMount(()=>{sync();window.addEventListener('hashchange',sync);return()=>window.removeEventListener('hashchange',sync)})</script>
<svelte:head><title>Until Every Cage · evidence desk</title></svelte:head><main><header class="top"><a class="wordmark" href="/v2-preview/#/">UNTIL EVERY CAGE <span>V2 / FIELD NOTE</span></a><a href="/ethics.html">Ethics &amp; safeguards ↗</a></header><section class="intro"><p class="eyebrow">EVIDENCE DESK · SYNTHETIC PREVIEW</p><h1>See what a record can—and cannot—tell us.</h1><p class="lede">A quiet, inspectable view of animal-agriculture locations. Every fixture below is fictional.</p></section><section class="toolbar" aria-label="Preview controls"><label>Profile<select bind:value={profile}><option value="curated">Curated release</option><option value="community">Community claims</option></select></label><label>Search locations<input aria-label="Search locations" bind:value={search} placeholder="Name, region, category" /></label><label>Region<select aria-label="Filter by region" bind:value={region}><option value="all">All regions</option>{#each [...new Set(locations.map(x=>x.region))] as option}<option value={option}>{option}</option>{/each}</select></label><label>State<select bind:value={scenario}><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option><option value="error">Error</option><option value="restricted">Restricted</option></select></label></section>{#if profile==='community'}<div class="warning" role="note"><strong>Unreviewed community claim</strong><span>Not verified by Until Every Cage.</span></div>{/if}{#if scenario==='loading'}<div class="state">Loading the fixture…</div>{:else if scenario==='empty'}<div class="state"><h2>No eligible records</h2></div>{:else if scenario==='error'}<div class="state error" role="alert"><h2>Could not load preview</h2></div>{:else if scenario==='restricted'}<div class="state"><h2>Preview withheld</h2></div>{:else}<div class="content"><aside><div class="list-head"><span>VISIBLE RECORDS</span><strong>{visibleLocations.length}</strong></div>{#each visibleLocations as location}<button class:active={selected?.id===location.id} onclick={()=>select(location.id)}><span class="dot"></span><span><strong>{location.name}</strong><small>{location.region} · {location.category}</small></span></button>{:else}<p>No records match these filters.</p>{/each}</aside><article>{#if selected}<p class="eyebrow">RECORD / {selected.id}</p><h2>{selected.name}</h2><p class="region">{selected.region} · {selected.category}</p><div class="rule"></div><div class="facts"><div><span>OBSERVED</span><strong>{selected.observed}</strong></div><div><span>MAP STATUS</span><strong>{selected.lat===null?'Not available':'Approximate display point'}</strong></div></div><div class="panel"><p class="eyebrow">PUBLICATION CONTEXT</p><strong>{profile==='community'?'Community-submitted · Community-unreviewed':'Government-sourced · Project-approved'}</strong><p>Source context remains attached to this synthetic record.</p></div>{/if}</article></div>{/if}<div class="phase-controls"><button onclick={()=>showMap=!showMap}>{showMap?'Hide map':'Show map'}</button><button onclick={()=>showExport=!showExport}>Preview export</button></div>{#if showMap}<MapView items={visibleLocations} selectedId={selected?.id??null}/>{/if}{#if showExport}<section class="export-preview"><p class="eyebrow">IN-MEMORY EXPORT PREVIEW</p><strong>{profile} · synthetic-2026.09</strong><p>Loaded results only. This preview is not a live or complete export.</p><pre>{exportPreview}</pre></section>{/if}<footer><span>Method preview · no live requests</span></footer></main>
